.studio-app {
  max-width: 520px;
  margin: 0 auto;
  font-family: Inter, sans-serif;
  color: #0f172a;
}
.app-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 0;
  border-bottom: 2px solid #e2e8f0;
}
.app-header h1 {
  font-size: 20px;
  margin: 0;
}
.badge {
  background: #dbeafe;
  color: #1d4ed8;
  padding: 4px 10px;
  border-radius: 9999px;
  font-size: 11.5px;
  font-weight: 600;
}
.team-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
  padding: 20px 0;
}
.profile-card {
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 16px;
  background: #f8fafc;
  text-align: center;
}
.avatar {
  font-size: 32px;
  margin-bottom: 6px;
}
.profile-name {
  font-size: 15px;
  font-weight: 700;
  margin: 0 0 4px 0;
}
.profile-role {
  font-size: 12.5px;
  color: #64748b;
  margin: 0;
}

